-- TrustVault schema (PostgreSQL). Generated by scripts/export_schema.py from the SQLAlchemy models.
-- Apply with scripts/init_db.py (it also applies db/hardening.sql: grants + the audit immutability trigger).

CREATE TABLE audit_logs (
	sequence_number BIGSERIAL NOT NULL,
	timestamp TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	actor_id UUID,
	actor_username VARCHAR(64),
	actor_role VARCHAR(32),
	action VARCHAR(64) NOT NULL,
	resource_type VARCHAR(32) NOT NULL,
	resource_id VARCHAR(64),
	ip_address VARCHAR(64) NOT NULL,
	user_agent VARCHAR(512) NOT NULL,
	status VARCHAR(16) NOT NULL,
	reason VARCHAR(255),
	metadata_json JSON NOT NULL,
	prev_hash VARCHAR(64) NOT NULL,
	row_hash VARCHAR(64) NOT NULL,
	PRIMARY KEY (sequence_number)
);
CREATE INDEX ix_audit_logs_action ON audit_logs (action);

CREATE TABLE rate_limit_buckets (
	key VARCHAR(128) NOT NULL,
	count BIGINT NOT NULL,
	window_start TIMESTAMP WITH TIME ZONE NOT NULL,
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (key)
);

CREATE TABLE users (
	id UUID NOT NULL,
	email VARCHAR(255) NOT NULL,
	username VARCHAR(64) NOT NULL,
	password_hash VARCHAR(255) NOT NULL,
	role VARCHAR(32) NOT NULL,
	is_active BOOLEAN NOT NULL,
	security_version INTEGER NOT NULL,
	failed_login_attempts INTEGER NOT NULL,
	locked_until TIMESTAMP WITH TIME ZONE,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE UNIQUE INDEX ix_users_username ON users (username);

CREATE TABLE documents (
	id UUID NOT NULL,
	owner_id UUID NOT NULL,
	pending_owner_id UUID,
	title VARCHAR(200) NOT NULL,
	category VARCHAR(100) NOT NULL,
	is_deleted BOOLEAN NOT NULL,
	deleted_at TIMESTAMP WITH TIME ZONE,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(owner_id) REFERENCES users (id),
	FOREIGN KEY(pending_owner_id) REFERENCES users (id)
);
CREATE INDEX ix_documents_owner_id ON documents (owner_id);
CREATE INDEX ix_documents_pending_owner_id ON documents (pending_owner_id);

CREATE TABLE email_change_tokens (
	id UUID NOT NULL,
	token_hash VARCHAR(64) NOT NULL,
	user_id UUID NOT NULL,
	new_email VARCHAR(255) NOT NULL,
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
	used_at TIMESTAMP WITH TIME ZONE,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX ix_email_change_tokens_token_hash ON email_change_tokens (token_hash);
CREATE INDEX ix_email_change_tokens_user_id ON email_change_tokens (user_id);

CREATE TABLE password_reset_tokens (
	id UUID NOT NULL,
	token_hash VARCHAR(64) NOT NULL,
	user_id UUID NOT NULL,
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
	used_at TIMESTAMP WITH TIME ZONE,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX ix_password_reset_tokens_token_hash ON password_reset_tokens (token_hash);
CREATE INDEX ix_password_reset_tokens_user_id ON password_reset_tokens (user_id);

CREATE TABLE sessions (
	id UUID NOT NULL,
	session_token_hash VARCHAR(64) NOT NULL,
	user_id UUID NOT NULL,
	user_security_version INTEGER NOT NULL,
	csrf_token_hash VARCHAR(64) NOT NULL,
	ip_address VARCHAR(64) NOT NULL,
	user_agent VARCHAR(512) NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	last_active_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
	revoked_at TIMESTAMP WITH TIME ZONE,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE INDEX ix_sessions_revoked_at ON sessions (revoked_at);
CREATE UNIQUE INDEX ix_sessions_session_token_hash ON sessions (session_token_hash);
CREATE INDEX ix_sessions_user_id ON sessions (user_id);

CREATE TABLE ai_suggestions (
	id UUID NOT NULL,
	document_id UUID NOT NULL,
	owner_id UUID NOT NULL,
	items JSON NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(document_id) REFERENCES documents (id),
	FOREIGN KEY(owner_id) REFERENCES users (id)
);
CREATE INDEX ix_ai_suggestions_document_id ON ai_suggestions (document_id);
CREATE INDEX ix_ai_suggestions_owner_id ON ai_suggestions (owner_id);

CREATE TABLE document_grants (
	id UUID NOT NULL,
	document_id UUID NOT NULL,
	grantee_user_id UUID NOT NULL,
	level VARCHAR(8) NOT NULL,
	granted_by UUID NOT NULL,
	granted_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	expires_at TIMESTAMP WITH TIME ZONE,
	revoked_at TIMESTAMP WITH TIME ZONE,
	PRIMARY KEY (id),
	FOREIGN KEY(document_id) REFERENCES documents (id),
	FOREIGN KEY(grantee_user_id) REFERENCES users (id),
	FOREIGN KEY(granted_by) REFERENCES users (id)
);
CREATE INDEX ix_document_grants_document_id ON document_grants (document_id);
CREATE INDEX ix_document_grants_grantee_user_id ON document_grants (grantee_user_id);

CREATE TABLE document_versions (
	id UUID NOT NULL,
	document_id UUID NOT NULL,
	version_number INTEGER NOT NULL,
	original_filename VARCHAR(255) NOT NULL,
	mime_type VARCHAR(128) NOT NULL,
	file_size_bytes BIGINT NOT NULL,
	storage_path VARCHAR(255) NOT NULL,
	blob BYTEA,
	encrypted_dek VARCHAR(255) NOT NULL,
	dek_nonce VARCHAR(32) NOT NULL,
	file_nonce VARCHAR(32) NOT NULL,
	sha256_hash VARCHAR(64) NOT NULL,
	uploaded_by UUID NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (document_id, version_number),
	FOREIGN KEY(document_id) REFERENCES documents (id),
	UNIQUE (storage_path),
	FOREIGN KEY(uploaded_by) REFERENCES users (id)
);
CREATE INDEX ix_document_versions_document_id ON document_versions (document_id);
